-- Pinned public IANA 2026f reference data from Moment Timezone 0.6.6 (MIT).
-- Source SHA256: 3103c5c0eaa879615da630b74e2373ad9b571e0eae992e0b2a3db6e4475de2ce.
-- Explicit coverage: 2020-01-01 inclusive through 2038-01-01 exclusive. No host tzdata fallback.
CREATE TABLE private.push_timezone_rules(name text PRIMARY KEY, version text NOT NULL CHECK(version='2026f'), valid_from timestamptz NOT NULL, valid_until timestamptz NOT NULL, initial_offset integer NOT NULL, transitions jsonb NOT NULL);
CREATE TABLE private.push_timezone_names(name text PRIMARY KEY, canonical text NOT NULL REFERENCES private.push_timezone_rules(name));
ALTER TABLE private.push_timezone_rules ENABLE ROW LEVEL SECURITY;
ALTER TABLE private.push_timezone_names ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON private.push_timezone_rules,private.push_timezone_names FROM PUBLIC,anon,authenticated,service_role;
CREATE FUNCTION private.push_local_time(zone_name text, at_time timestamptz) RETURNS timestamp
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$
DECLARE r private.push_timezone_rules; offset_seconds integer;
BEGIN
 SELECT z.* INTO r FROM private.push_timezone_names n JOIN private.push_timezone_rules z ON z.name=n.canonical WHERE n.name=zone_name;
 IF NOT FOUND THEN RAISE EXCEPTION 'push:invalid_timezone'; END IF;
 IF at_time IS NULL OR at_time<r.valid_from OR at_time>=r.valid_until THEN RAISE EXCEPTION 'push:timezone_out_of_range'; END IF;
 SELECT (t->>1)::integer INTO offset_seconds FROM jsonb_array_elements(r.transitions) t WHERE (t->>0)::bigint<=extract(epoch FROM at_time) ORDER BY (t->>0)::bigint DESC LIMIT 1;
 RETURN (at_time AT TIME ZONE 'UTC')+make_interval(secs=>coalesce(offset_seconds,r.initial_offset));
END $$;
REVOKE ALL ON FUNCTION private.push_local_time(text,timestamptz) FROM PUBLIC,anon,authenticated,service_role;
CREATE OR REPLACE FUNCTION private.push_quiet_at(p private.push_defaults,at_time timestamptz) RETURNS boolean
LANGUAGE sql STABLE SET search_path='' AS $$
 SELECT coalesce(p.quiet_enabled AND (p.quiet_start=p.quiet_end OR
  CASE WHEN p.quiet_start<p.quiet_end THEN private.push_local_time(p.quiet_zone,at_time)::time>=p.quiet_start AND private.push_local_time(p.quiet_zone,at_time)::time<p.quiet_end
  ELSE private.push_local_time(p.quiet_zone,at_time)::time>=p.quiet_start OR private.push_local_time(p.quiet_zone,at_time)::time<p.quiet_end END),false)
$$;
CREATE OR REPLACE FUNCTION public.notification_preferences(p_patch jsonb DEFAULT NULL) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE who uuid:=auth.uid(); p private.push_defaults; k text;
BEGIN
 PERFORM private.delayed_actor(who);
 IF p_patch IS NOT NULL THEN
  IF jsonb_typeof(p_patch)<>'object' THEN RAISE EXCEPTION 'push:invalid_preferences'; END IF;
  FOR k IN SELECT jsonb_object_keys(p_patch) LOOP
   IF k IN('asyncDefault','newTable','quietEnabled') THEN
    IF jsonb_typeof(p_patch->k)<>'boolean' THEN RAISE EXCEPTION 'push:invalid_preferences'; END IF;
   ELSIF k IN('quietStart','quietEnd') THEN
    IF jsonb_typeof(p_patch->k)<>'string' OR p_patch->>k !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$' THEN RAISE EXCEPTION 'push:invalid_time'; END IF;
   ELSIF k='quietZone' THEN
    IF jsonb_typeof(p_patch->k)<>'string' OR NOT EXISTS(SELECT FROM private.push_timezone_names WHERE name=p_patch->>k) THEN RAISE EXCEPTION 'push:invalid_timezone'; END IF;
   ELSE RAISE EXCEPTION 'push:invalid_preferences'; END IF;
  END LOOP;
  UPDATE private.push_defaults SET enabled=coalesce((p_patch->>'asyncDefault')::boolean,enabled),
   new_table_enabled=coalesce((p_patch->>'newTable')::boolean,new_table_enabled),
   quiet_enabled=coalesce((p_patch->>'quietEnabled')::boolean,quiet_enabled),
   quiet_start=coalesce((p_patch->>'quietStart')::time,quiet_start),quiet_end=coalesce((p_patch->>'quietEnd')::time,quiet_end),
   quiet_zone=coalesce(p_patch->>'quietZone',quiet_zone) WHERE user_id=who;
  -- Wake deferred work after zone/window edits; Last Call still checks its real due time.
  UPDATE private.push_deliveries d SET retry_at=clock_timestamp() FROM private.push_events e
   WHERE e.id=d.event_id AND e.user_id=who AND d.state='pending';
  -- An explicit opt-out cancels old pending work, even if the user later opts in again.
  IF p_patch->>'newTable'='false' THEN
   UPDATE private.push_deliveries d SET state='skipped',lease=NULL,lease_until=NULL FROM private.push_events e
    WHERE e.id=d.event_id AND e.user_id=who AND e.kind='table_open' AND d.state IN('pending','sending');
  END IF;
 END IF;
 SELECT * INTO p FROM private.push_defaults WHERE user_id=who;
 RETURN jsonb_build_object('asyncDefault',coalesce(p.enabled,false),'newTable',coalesce(p.new_table_enabled,false),
  'quietEnabled',coalesce(p.quiet_enabled,false),'quietStart',coalesce(to_char(p.quiet_start,'HH24:MI'),'22:00'),
  'quietEnd',coalesce(to_char(p.quiet_end,'HH24:MI'),'07:00'),'quietZone',coalesce(p.quiet_zone,'UTC'));
END $$;
